// BuiltinParamByID looks up a built-in parameter by id.
func BuiltinParamByID(id int64) (BuiltinParam, bool) {
	p, ok := builtinParams[id]
	return p, ok
}

// SearchBuiltinParams returns entries whose enum name or display name
// contains s (case-insensitive) — the entry point for mapping parameter
// values to names.
func SearchBuiltinParams(s string) []BuiltinParam {
	var out []BuiltinParam
	needle := strings.ToLower(s)
	for _, p := range builtinParams {
		if strings.Contains(strings.ToLower(p.EnumName), needle) ||
			strings.Contains(strings.ToLower(p.DisplayName), needle) {
			out = append(out, p)
		}
	}
	return out
}
